"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6340],{57473:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ArmorConfig","desc":"Single tuning surface for crafted player armor. Each tier provides a base\\n% incoming-damage reduction; the Armor perk (`ArmorEfficiency`) multiplies it.\\nTier is the persisted unit (see `ArmorManager`); base reduction is always\\nderived from this table, so retuning a tier retroactively updates every player\\nholding it. Per project convention, tune armor here, not in code.","source":{"line":11,"path":"src/ReplicatedStorage/SharedModules/Configs/ArmorConfig.luau"}}')}}]);